reads.command:
python3 -c "import pandas as pd; import numpy as np; df = pd.read_csv('train.csv'); best_acc = 0; best_feat = ''; best_thresh = 0; 
for col in df.columns[:-1]:
    vals = df[col].values
    target = df['target'].values
    for thresh in np.percentile(vals, [25, 50, 75]):
        acc = ( (vals > thresh) == target ).mean()
        if acc < 0.5: acc = 1 - acc
        if acc > best_acc:
            best_acc = acc
            best_feat = col
            best_thresh = thresh
print(f'Best acc: {best_acc}, feat: {best_feat}, thresh: {best_thresh}')"

