import pandas as pd
import numpy as np


TARGET_COLUMN = 'target'

class DecisionTree:
    def __init__(self, max_depth=3):
        self.max_depth = max_depth
        self.tree = None

    def fit(self, X, y):
        self.tree = self._grow_tree(X, y)

    def _grow_tree(self, X, y, depth=0):
        n_samples, n_features = X.shape
        n_labels = len(np.unique(y))

        if (depth >= self.max_depth or n_labels <= 1 or n_samples < 10):
            leaf_value = self._most_common_label(y)
            return leaf_value

        feat_idxs = np.arange(n_features)
        best_feat, best_thresh = self._best_split(X, y, feat_idxs)

        if best_feat is None:
            return self._most_common_label(y)

        left_idxs, right_idxs = self._split(X[:, best_feat], best_thresh)
        left = self._grow_tree(X[left_idxs, :], y[left_idxs], depth + 1)
        right = self._grow_tree(X[right_idxs, :], y[right_idxs], depth + 1)
        return (best_feat, best_thresh, left, right)

    def _best_split(self, X, y, feat_idxs):
        best_gain = -1
        split_idx, split_thresh = None, None
        for feat_idx in feat_idxs:
            X_column = X[:, feat_idx]
            thresholds = np.unique(X_column)
            # To speed up, only check 10 thresholds
            if len(thresholds) > 50:
                thresholds = np.percentile(X_column, np.linspace(0, 100, 50))

            for thresh in thresholds:
                gain = self._information_gain(y, X_column, thresh)
                if gain > best_gain:
                    best_gain = gain
                    split_idx = feat_idx
                    split_thresh = thresh
        return split_idx, split_thresh

    def _information_gain(self, y, X_column, thresh):
        parent_entropy = self._entropy(y)
        left_idxs, right_idxs = self._split(X_column, thresh)
        if len(left_idxs) == 0 or len(right_idxs) == 0:
            return 0
        n = len(y)
        n_l, n_r = len(left_idxs), len(right_idxs)
        e_l, e_r = self._entropy(y[left_idxs]), self._entropy(y[right_idxs])
        child_entropy = (n_l / n) * e_l + (n_r / n) * e_r
        return parent_entropy - child_entropy

    def _entropy(self, y):
        hist = np.bincount(y)
        ps = hist / len(y)
        return -np.sum([p * np.log2(p) for p in ps if p > 0])

    def _split(self, X_column, split_thresh):
        left_idxs = np.argwhere(X_column <= split_thresh).flatten()
        right_idxs = np.argwhere(X_column > split_thresh).flatten()
        return left_idxs, right_idxs

    def _most_common_label(self, y):
        if len(y) == 0: return 0
        return np.bincount(y).argmax()

    def predict(self, X):
        return np.array([self._traverse_tree(x, self.tree) for x in X])

    def _traverse_tree(self, x, node):
        if not isinstance(node, tuple):
            return node
        feat_idx, thresh, left, right = node
        if x[feat_idx] <= thresh:
            return self._traverse_tree(x, left)
        return self._traverse_tree(x, right)


def predict(train_csv: str, test_csv: str, output_csv: str) -> None:
    train = pd.read_csv(train_csv)
    test = pd.read_csv(test_csv)

    X_train = train.drop(columns=[TARGET_COLUMN]).values
    y_train = train[TARGET_COLUMN].values
    X_test = test.drop(columns=[TARGET_COLUMN]).values

    dt = DecisionTree(max_depth=6)
    dt.fit(X_train, y_train)
    predictions_binary = dt.predict(X_test)

    predictions = pd.DataFrame({"prediction": predictions_binary})
    predictions.to_csv(output_csv, index=False)

